 // Tilt bearings at +-outerX, shared by inner/outer frames.
 for(int i=0;i<2;i++){
  float signX=i==0?-1.:1.;float3 c=rz(float3(signX*1.23,0.,0.),a);
  part(o,d,c,a+1.5707963,1.5707963,.115,0.,.14,3.,best,normal,local,material);
